# 第 1 批：卦 1-8（乾、坤、屯、蒙、需、讼、师、比）
# 人话 = 忠实转写「取象/义理」原义为现代口语，不作占断、不按事项给吉凶。

HEXAGRAMS = {
  "1": {
    "zh": "乾卦六爻全是阳，纯粹刚健。它讲的是靠自己不断进取、越来越强的劲头；同时提醒你：太满了要往回收。顺序不能乱——先立住根基，再谈通达和持守。",
    "en": "Qian has all six lines yang — pure strength. It's about driving yourself forward under your own power, getting stronger. But it warns: when you're full, pull back. The order can't be skipped — establish the root first, then smooth progress and staying steady.",
    "ja": "乾は六爻すべて陽で、純粋な剛健。自分の力で前へ進み、強くなることを表す。ただ満ちすぎたら引け、とも戒める。順番は狂わせない——まず基盤を立て、それから順調さと持守を語る。",
  },
  "2": {
    "zh": "坤卦六爻全是阴，柔顺承载。它讲的是像大地一样厚道、能包容万物的量，以及看懂苗头、守住安静的智慧。开头会迷路，顺着大势走就找到主心骨了。",
    "en": "Kun has all six lines yin — yielding and bearing. It's about the largeness of spirit that carries all things like the earth, and the wisdom to read the early signs and stay still. You may feel lost at first; follow the larger current and you'll find your anchor.",
    "ja": "坤は六爻すべて陰で、柔順にものを支える。大地のように万物を包容する器の大きさと、兆しを読み静けさを守る知恵を表す。最初は迷うが、大きな流れに従えば拠り所が見つかる。",
  },
  "3": {
    "zh": "屯卦下震上坎，一动就遇上险。它讲的是万事开头难——像种子顶着土往外拱。要紧的是拿捏进退的分寸，不在求快，而在先把根扎稳。",
    "en": "Zhun is thunder below, water above — you move and meet danger. It's about how hard every beginning is, like a seed pushing through soil. What matters is calibrating advance and retreat — not speed, but putting down roots first.",
    "ja": "屯は下が震、上が坎。動けばすぐ険にあたる。すべての始まりが難しいことを表す——土を押しのけて出ようとする種のよう。肝心なのは進退の加減で、速さではなくまず根を下ろすこと。",
  },
  "4": {
    "zh": "蒙卦下坎上艮，前有险、到此为止。它讲的是蒙昧待启——来求教的人要诚心自己来问，问一次就答；反复没完没了地追问，就不再答了。启蒙之道，贵在正当。",
    "en": "Meng is water below, mountain above — danger ahead, and a stop. It's about ignorance waiting to be opened: the seeker must come sincerely on their own; ask once and you'll be answered. Ask the same thing over and over and you won't be answered again. The way of teaching what's right.",
    "ja": "蒙は下が坎、上が艮。前には険、ここで止まる。まだ開けていない知が教えを待つことを表す——教えを請う者は誠心で自ら来る。一度問えば答える。同じことを繰り返し問えば、もう答えない。導く道は正しさを尊ぶ。",
  },
  "5": {
    "zh": "需卦下乾上坎，刚健碰上险。它讲的是等待的分寸——不急躁，一步一步蹚过险，不是一味往前冲。该等就等，等得有度。",
    "en": "Xu is strength below, danger above. It's about the measure of waiting — not impatient, wading through danger step by step, not charging blindly ahead. Wait when you should, and wait with measure.",
    "ja": "需は下が乾、上が坎。剛健が険にぶつかる。待つことの加減を表す——焦らず、一歩ずつ険を渡り、むやみに突き進まない。待つべき時に待ち、度を守って待つ。",
  },
  "6": {
    "zh": "讼卦下坎上乾，心里有险、外表刚强。它讲的是争讼怎么停下来：堵住了也能疏通，肯在中道上止步，争执就不会没完；以退让为贵。",
    "en": "Song is danger below, strength above — danger inside, rigidity without. It's about how to stop a dispute: what's blocked can open up; stop at the midpoint and the quarrel won't drag on. Yielding is what counts.",
    "ja": "訟は下が坎、上が乾。内に険、外に剛。争いをどう鎮めるかを表す——行き詰まっても通じる道があり、中途で止めれば争いは長引かない。譲ることを尊ぶ。",
  },
  "7": {
    "zh": "师卦下坎上坤，有险而能顺。它讲的是带队伍有章法：出兵要有正当名义，纪律立在头里——用人靠的是规矩严明，不是人多。",
    "en": "Shi is danger below, yielding above. It's about leading people with method: a just cause to act, and discipline laid down first — you lead by clear rules, not by numbers.",
    "ja": "師は下が坎、上が坤。険があって従う。人を率いる道を表す——出るには正しい名分、規律がまず第一。人を統べるのは人数ではなく、きちんとした掟である。",
  },
  "8": {
    "zh": "比卦下坤上坎，顺而相亲。它讲的是亲近、团结要有分寸：跟错了人就出问题——所以第一要紧的，是谨慎挑你要亲近的人。",
    "en": "Bi is yielding below, danger above — closeness in accord. It's about drawing near and uniting with measure: align with the wrong person and it goes wrong — so the first priority is choosing carefully whom you're close to.",
    "ja": "比は下が坤、上が坎。従って親しむ。親しみや結束には加減があることを表す——間違った者と結べば狂う。まず大事なのは、誰と親しむかを慎んで選ぶこと。",
  },
}

LINES = {
  # 1 乾
  "1-0": {"zh": "你还在最底下，时机没到。就像龙潜在水里还没露头——这时候别急着表现，先把自己的本事养足；现在就往外冲，反而养不住底气。", "en": "You're at the very bottom and the time hasn't come. Like a dragon under water, not showing its head — don't rush to be seen; build up your ability first. Pushing out now only drains what you're trying to grow.", "ja": "まだ一番下にいて、時が来ていない。水に潜む龍がまだ顔を出さないようなもの。今は目立とうとせず、まず自分の力を養うこと。ここで外へ急げば、かえって養っているものを失う。"},
  "1-1": {"zh": "你已经有本事、也开始被看见了，但还没到大展身手的时候。这时可以出来跟人打交道了——要紧的是站稳正当的位置，不是一味求快。", "en": "You've got ability and are starting to be seen, but it's not yet time for a full display. You can come out and engage with people now — what matters is standing on proper ground, not chasing speed.", "ja": "実力もあり見え始めてもいるが、まだ本格的に活躍する時ではない。ここで人と交わってよい。肝心なのは正しい場所に立つこと、急ぐことではない。"},
  "1-2": {"zh": "你在下卦的最上面，过于刚强又不居中，卡在上下之间、进退难定。办法是白天黑夜都不松懈地进修自己，时时警醒——这样即使在险地，也不至于失守。", "en": "You're at the top of the lower trigram — too rigid, off-center, stuck between above and below, unsure whether to advance or retreat. The answer: keep refining yourself day and night, stay alert. Then even on dangerous ground you won't lose your footing.", "ja": "下卦の最上部にいて、剛すぎて真ん中を外れ、上下の間で進退がつかない。日夜みずからを磨き、常に警戒すること。そうすれば険しい場所でも足を崩さずに済む。"},
  "1-3": {"zh": "你快要往上走了，但还没打定主意——好在身后就是渊，随时能退。看清时机再动：能进就进，不对就退。犹豫着不贸然出手，本身也是一种自保。", "en": "You're about to move up but haven't decided — luckily the deep is right behind you, so you can pull back anytime. Size up the moment before acting: advance when you can, retreat when you can't. Holding off when unsure is itself a way to stay safe.", "ja": "もう上へ進もうとしているが、まだ決めかねている——幸い背後には淵があり、いつでも引ける。時を見極めて動くこと。進めるなら進み、駄目なら引く。迷って安易に動かないのも、自分を守る道だ。"},
  "1-4": {"zh": "你到了尊位，居中又端正，是全卦的主爻。德行和位置相称，就可以真正做点事——要紧的是你的德配得上这个位子。", "en": "You've reached the place of honor — centered and upright, the main line of the whole hexagram. With character matching position, you can genuinely accomplish something. What matters is that your virtue fits the station.", "ja": "尊い位に就き、真ん中で正しく、全卦の主爻。徳と地位が釣り合えば、本当に事を成せる。肝心なのは、自分の徳がその位に見合うこと。"},
  "1-5": {"zh": "你冲到了顶，再往上没路了——太满的东西撑不久。只知进、不知退，就会留下悔恨。守住满局的诀窍，是主动减损一点。", "en": "You've climbed to the top — nowhere higher to go, and what's overfull can't last. Knowing only advance, not retreat, brings regret. The way to keep a full hand is to willingly give a little back.", "ja": "頂点まで来て、もう上へ行く所がない。満ちすぎたものは長く保てない。進むことだけ知り引くことを知らなければ悔いを残す。満ちを保つコツは、自ら少し減らすこと。"},
  # 2 坤
  "2-0": {"zh": "脚底下刚结了一层霜，照这势头下去会结成厚冰。苗头刚冒出来就要警觉——别等事情成了才反应过来，开头最要紧。", "en": "There's frost underfoot; at this rate it will harden into thick ice. Catch the small signs early — don't wait until things are done before reacting. The beginning is what matters most.", "ja": "足元に薄い霜が降りた。この勢いなら厚い氷になる。小さな兆しのうちに気づくこと——事ができてから気づいては遅い。初めが何より大事。"},
  "2-1": {"zh": "你在下卦正中，得位又居中，品德正直而广大。内在直、外在方，是自然长成的，不用装；守住正，走的自然就通。", "en": "You're at the center of the lower trigram — in the right place and centered, with virtue upright and broad. Straight within, square without — it grows naturally, no pretense needed. Hold to what's right and your path opens by itself.", "ja": "下卦の中央で、位も中も得て、徳は素直で広い。内は直く外は方正、それは自然に育ったもので饰る必要はない。正を守れば、道は自ずと通じる。"},
  "2-2": {"zh": "你在下卦上面，不中不正，才华是藏着没发出来的。有本事别急着张扬，守住本分就行；跟着别人做事不居功，反而能有好结果。", "en": "You're at the top of the lower trigram — off-center and improper, your talent held in, not yet shown. Don't rush to show off; just keep to your duty. Serve others without claiming credit, and you'll get a good result.", "ja": "下卦の上部にいて、中も正も外れ、才はしまったまま出ていない。急にひけらかさず本分を守ること。人の仕事を助けて功を奪わなければ、かえって良い結果が得られる。"},
  "2-3": {"zh": "你在上卦下面，靠近五位却合不来，处在容易招猜疑的位置。把嘴管紧、像扎住口袋一样别乱说——在这种尴尬处境，沉默就够自保，不必求什么好名声。", "en": "You're below the upper trigram, near the fifth place but not in sync — a spot prone to suspicion. Keep your mouth shut like a tied sack. In this awkward spot, silence alone protects you; you needn't chase a good name.", "ja": "上卦の下にいて、五位に近いのにうまく合わず、疑われやすい場所にいる。口を結んだ袋のように緘すること。この気まずい状況では、黙っているだけで身は守れる。評判を求める必要はない。"},
  "2-4": {"zh": "你身居尊位，以柔守中，就像黄色的下裳——贵气藏在内里。在上位却不僭越，用中道守住自己，文采在里面而不外露。", "en": "You're in the place of honor, holding the center with softness — like a yellow lower robe: nobility kept inside. In high position you don't overstep; you guard yourself with the middle way, your grace within rather than displayed.", "ja": "尊い位にいて、柔らかく中を守る——黄色い下衣のような、気高さを内に秘めた姿。上位にいて分を越えず、中庸で自分を守る。美しさは内にあり、外に誇示しない。"},
  "2-5": {"zh": "阴柔到了极点，就跟阳刚争起来了——两股气在外面相斗。走到这一步是路到头了：柔到了极处维持不住，事物一到极端就会反转。", "en": "Yin softness at its extreme starts contending with yang — two forces clash out in the open. This is the end of the road: softness at its limit can't hold, and anything pushed to extremes flips.", "ja": "陰の柔が極に達すると陽と争い始める——二つの気が外でぶつかる。ここまで来れば道は終わり。柔も極まれば保てず、物は極すれば必ず反転する。"},
  # 3 屯
  "3-0": {"zh": "你本性爱动，可前面就是险，所以只能原地打转、迈不开步。这时候别硬闯——先把根基扎稳，比急着赶路强。", "en": "You're eager to move, but danger lies ahead, so you pace in place, unable to advance. Don't force it — put down roots first; that beats rushing down the road.", "ja": "動きたくてうずうずするが、前には険がある。そのためその場をぐるぐる回って進めない。無理に突き進まず、まず根を下ろすこと。急ぐよりましだ。"},
  "3-1": {"zh": "你心里想的是正经目标，中间却隔着阻碍，一时够不着，只能来回徘徊。方向没错，是时机没到——守住正道慢慢等，久了自然能通。", "en": "You're aiming at something proper, but obstacles stand between, so you circle around, unable to reach it. Your direction is right; the timing hasn't arrived. Hold to what's right and wait — in time it opens up.", "ja": "心には正しい目標があるが、間に障害があり届かず、行ったり来たりしている。進む先は間違っていない。ただ時がまだ来ていないだけ。正を守って待てば、やがて通じる。"},
  "3-2": {"zh": "你没引路人，却贪着往外追东西，结果一头扎进险境。没有向导就别乱追——看出不对趁早放手才是聪明；贪着往前不回头，只会把自己困住。", "en": "You have no guide but you're chasing after things anyway, and you've wandered into danger. Without a guide, don't chase blindly — seeing the signs and letting go is the smart move. Greedily pushing on without looking back only traps you.", "ja": "案内人もいないのに物を追いかけ、気づけば険の中に飛び込んでいた。導きがないなら無闇に追うな。兆しを見て早めに諦めるのが賢い。貪って進み振り返らなければ、行き詰まるだけだ。"},
  "3-3": {"zh": "你正应下面的初爻，主动过去就能配上。犹豫的人只会原地打转，果断迈步的人才能得到。", "en": "You have a proper match in the first line below; go to them and you'll connect. Those who hesitate keep circling; those who move decisively get what they seek.", "ja": "下の初爻と正しく応じている。自ら近づけば巡り合える。迷う者はその場を回り続け、断ち切って動く者が得る。"},
  "3-4": {"zh": "你身居高位，却陷在坎险之中，恩泽施不广。这种处境能顾的只是小范围——小事还能守住，大事就力不从心了。", "en": "You're in high position but stuck inside the danger, unable to extend your reach widely. In this spot your scope is narrow — small matters you can still manage, but big ones are beyond your strength.", "ja": "高い位にいながら坎の険の中に陥り、恩恵を広げられない。この状況では及ぶ範囲が狭い——小さなことは守れるが、大きなことは力が及ばない。"},
  "3-5": {"zh": "你走到了屯卦的尽头，前无去路，身边又没有能帮上忙的人——只能伤心落泪。这是进退都难的绝境，硬撑没用，得先承认这个难、去求援。", "en": "You've reached the end of Zhun — no road ahead, no one nearby to help, so all you can do is weep. It's a deadlock with no way forward or back; pushing alone won't help. Acknowledge the difficulty and seek help.", "ja": "屯の終わりに来て、行く先もなく、助けてくれる者もいない——ただ涙を流すばかり。進むも引くも叶わぬ行き詰まりで、一人で頑張っても意味がない。難しさを認め、助けを求めること。"},
  # 4 蒙
  "4-0": {"zh": "你处在蒙昧的开端，上面有九二可以启发你，但只能引、不能纵。启发要靠立规矩——规矩立住了才能脱开束缚；一味宽松，反而误了教。", "en": "You're at the start of ignorance, with the second line above able to enlighten you — but it can guide, not indulge. Enlightenment needs rules set: with rules in place you can slip free of bonds; pure leniency spoils the teaching.", "ja": "まだ蒙昧の始まりで、上の九二が導いてくれる。ただ導くことはできても甘やかすことはできない。目を開くには掟を立てること。掟が立って初めて束縛から抜けられる。ただ寛大にすれば、かえって教えを損なう。"},
  "4-1": {"zh": "你是全卦的主爻，居中能包容众人的蒙昧。教人贵在能容——容得下才能感化；刚强又居中，所以能担起家、带好队伍。", "en": "You're the main line of the hexagram — centered, able to hold the ignorance of the many. Teaching thrives on tolerance: only by holding people can you transform them. Strong yet centered, you can carry a household and lead.", "ja": "全卦の主爻で、真ん中にいて多くの者の蒙昧を包み込める。教えるには容れることが肝心——容れて初めて人を感化できる。剛でありながら中を得ているので、家を担い人を率いられる。"},
  "4-2": {"zh": "你在下卦上面，不中不正，丢了该应的对象去追上九。见了利就失了操守，等于自己放弃了立身之本——跟错了人，去了也不会有什么收获。", "en": "You're at the top of the lower trigram — off-center and improper, abandoning your proper match to chase the top line. Seeing gain, you lose your principles — that's abandoning yourself. Following the wrong person, you'll gain nothing.", "ja": "下卦の上部にいて、中も正も外れ、応じるべき相手を捨てて上九を追う。利益を見て操守を失うのは、自分を捨てること。間違った者に従えば、行っても得るものはない。"},
  "4-3": {"zh": "你在上卦下面，独自远离阳爻，上下都是阴，没人能帮你。困住又不肯学，就一直蒙下去——处境偏、又没明师指点，路就走死了。", "en": "You're below the upper trigram, far from any yang line, surrounded above and below by yin, with no help. Stuck and refusing to learn, you stay ignorant — a lopsided spot with no good teacher, and the road closes.", "ja": "上卦の下にいて、陽から離れ、上下とも陰で助ける者がない。困ってまだ学ばなければ、蒙昧なまま。場所が偏り、良い師の導きもなく、道は行き詰まる。"},
  "4-4": {"zh": "你身居尊位，柔和居中，以孩童般虚心来求教。虚怀接受别人，教的人就乐意告诉你；地位高却不自以为是，这正是你能明白的道理。", "en": "You're in the place of honor, soft and centered, seeking teaching with a child's open mind. Receive others with humility and the teacher is glad to tell you. High in station yet not self-satisfied — that's why you can understand.", "ja": "尊い位にいて、柔らかく中を守り、童子のような素直な心で教えを請う。虚な心で人を受け入れれば、教える者も喜んで告げる。位が高くても自分を正しいと決めつけない——だからこそ明るくなれる。"},
  "4-5": {"zh": "你到了卦的顶，用刚强去治蒙昧，过了头、失了柔。治蒙太严反而成了害——刚的作用在于挡住外面的诱惑，不在于攻打人的本心。", "en": "You're at the top of the hexagram, using rigidity to deal with ignorance — overdoing it, losing softness. Too harsh and it becomes harm. Rigidity's role is to fend off outside temptation, not to attack a person's heart.", "ja": "卦の頂点で、剛強をもって蒙昧を治めようとし、度を越して柔を失った。あまりに厳しければ、かえって害になる。剛の働きは外の誘いを防ぐことにあり、人の本心を攻めることではない。"},
  # 5 需
  "5-0": {"zh": "你离坎险最远，可以守着常规慢慢等。等待的诀窍是有恒心——一急躁就乱了方寸；守住常态，才能躲开祸害。", "en": "You're farthest from the danger, so you can keep to the ordinary and wait. The secret of waiting is constancy — impatience breaks your rhythm; holding to the normal keeps harm away.", "ja": "険から最も遠く、平常を保って待てる。待つコツは根気。焦れば平常心を失い、平常を守れば害を遠ざけられる。"},
  "5-1": {"zh": "你渐渐靠近险了，还没进去，外面已有闲言碎语。别人的话可以听，但别为所动——守好自己那份中道，最后反而能顺。", "en": "You're edging toward danger but haven't entered; already there's talk around you. Hear what people say but don't be moved — hold your center and you'll come out fine.", "ja": "少しずつ険に近づいたが、まだ入っていない。周りで噂が出始めている。人の言葉は聞いても動じるな。真ん中を保てば、最後はうまく収まる。"},
  "5-2": {"zh": "你已经贴到险边上了，性子又太刚、不肯收——这是自己把祸招来。处在危险处，退一步就能免灾，可你偏偏不退。", "en": "You're right up against the danger, too rigid to back off — you're bringing trouble on yourself. In danger, one step back would save you, but you won't take it.", "ja": "険にすっかり近づき、剛すぎて引けない——自分で禍を招いている。危ない場所では一歩引けば免れるのに、どうしても引かない。"},
  "5-3": {"zh": "你已经陷进险里了，但因为柔顺、不硬顶，反而能脱身。入了险就顺着势、听其自然才能出来；硬碰硬，就卡住拔不出来了。", "en": "You're already in the danger, but because you're yielding and don't fight head-on, you can get out. Once in, follow the current and you'll emerge; fight it rigidly and you'll be stuck.", "ja": "すでに険の中にいるが、柔順で逆らわないため、かえって抜け出せる。険に入ったら流れに従えば出られる。剛に争えば行き詰まって抜けなくなる。"},
  "5-4": {"zh": "你位子稳、又得中得正，可以安心等着。你的底气够自己过日子，从容等时机就行——内在充实了，不用向外求，需要什么自己就有。", "en": "Your position is secure, centered and correct, so you can wait with ease. You have enough to sustain yourself; wait for the moment calmly. Full inside, you don't need to seek outside — what you need is there.", "ja": "地位が安定し、中も正も得ているので安心して待てる。自分を養うものは十分あり、余裕を持って時を待つばかり。内が充実していれば外に求めず、必要なものは自ずとある。"},
  "5-5": {"zh": "等到了头，形势就变了——下面三个阳爻主动找上门来。你柔顺、不拒绝，客客气气接待他们就好。柔能化解刚，这就是这一爻的道理。", "en": "Waiting reaches its end and the situation shifts — three yang lines come to you on their own. Be yielding, don't refuse them; receive them with respect. Softness overcomes hardness — that's the point of this line.", "ja": "待つことも極まれば状況が変わり、下から三つの陽が自ら訪ねてくる。柔らかく拒まず、丁寧に迎えること。柔は剛に勝つ——これがこの爻の道理。"},
  # 6 讼
  "6-0": {"zh": "你性子柔、不爱争，争讼刚起头你就想收手——这是对的。争执拖久了两边都伤；有点口角就赶紧打住，是最会处理争执的做法。", "en": "You're soft and don't like to fight; the moment a dispute starts you want to stop — that's right. Disputes dragged out hurt both sides; a few harsh words then stopping is the skillful way.", "ja": "柔らかく争わない性質で、争いが始まったばかりで早くも止めたいと思う——それで正しい。争いを長引かせれば双方が傷つく。少し言い合ってすぐ止めるのが、上手な処理だ。"},
  "6-1": {"zh": "你跟上面正面对上了，但明知赢不了就退了——这是明智，不是怂。退下来守住自己，保住你和你的人，比硬拼下去强。", "en": "You're up against someone above, but knowing you can't win, you back off — that's wise, not cowardly. Retreat and hold your ground; protecting yourself and your people beats a losing fight.", "ja": "上の者と正面からぶつかったが、勝てないと知って引いた——これは賢明で臆病ではない。引いて自分を守り、自分と仲間を保つこと。無理に戦うよりましだ。"},
  "6-2": {"zh": "争执中你守着本分不掺和，跟着上头做事也不抢功。守住老实样子就能避开争；有功不往自己身上揽，就不会惹祸。", "en": "In a dispute, you keep to your old ways and don't join in; you serve those above without claiming credit. Staying steady avoids the fight; not taking credit keeps trouble away.", "ja": "争いの中で旧来の徳を守って加わらず、上の仕事を助けても功を奪わない。いつもの姿を保てば争いを避けられる。功があっても自分のものにしないので、禍が及ばない。"},
  "6-3": {"zh": "你认识到这场争打不赢，就回到正理上来了。知道自己不对就改，重新按正道走——把争的心收起来、安分守己，这就叫重新开始。", "en": "You realize this fight can't be won and return to what's right. Knowing your fault, you change and come back to the proper path — putting aside the urge to contend and settling into your place: that's a fresh start.", "ja": "この争いでは勝てないと悟り、正しい道理に立ち返った。自分の非を知って改め、正道に戻る。争う心を捨てて分を守る——これが改心だ。"},
  "6-4": {"zh": "你处在裁断的位置，又中又正，能不偏不私地处理争执。判断的要点在于公正，不在于谁赢谁输。", "en": "You're in the judging seat, centered and correct, able to handle disputes without bias. The essence of judging is fairness, not who wins.", "ja": "裁く立場にいて、中も正も保ち、私情なしに争いを裁ける。裁断の要は公平さであって、勝敗ではない。"},
  "6-5": {"zh": "你靠争讼赢了、得了赏，但这来得不正，很快又被夺回去。靠争抢得来的，也会靠争抢失去——这种侥幸的东西，根本荣耀不了你。", "en": "You won the dispute and got a reward, but it came wrongly and will soon be stripped away. What you gain by fighting, you lose by fighting — such a windfall can never bring you honor.", "ja": "争いに勝って褒美を得たが、その得方が正しくなく、すぐに奪い返される。争って得たものは争って失う。そのような僥倖は身を輝かせるには足りない。"},
  # 7 师
  "7-0": {"zh": "队伍刚拉起来，第一件事就是号令统一、纪律严明。人多不用怕，怕的是没规矩——纪律松了，人再多也不听使唤，事情一定砸。", "en": "A group has just formed; the first thing is unified command and strict discipline. Numbers aren't the worry — lack of rules is. Loose discipline means even a crowd won't obey, and the effort will fail.", "ja": "隊伍ができたばかり。まず必要なのは号令の統一と規律の厳しさ。人数ではなく規律が問題だ。規律が緩めば人が多くても従わず、事は必ず失敗する。"},
  "7-1": {"zh": "你是队伍的主心骨，上面也信任你、把指挥权交给你。当头领的道理是：刚强又能守中，众人就服你——上面信任、下面也服气。", "en": "You're the backbone of the group, and those above trust you with command. Leading means being strong yet centered — then people follow you. Trusted above, believed in below.", "ja": "隊伍の中心人物で、上からも信頼され指揮を任されている。将たる道は、強く中を保てば衆が従う——上に信され、下にも信じられる。"},
  "7-2": {"zh": "你本事不够却担着重任，位置又不正，大家不听你的。用人不当，队伍就散、事就办不成——量才授任，是用人的关键。", "en": "Your ability is weak but the burden is heavy, and your place is off, so no one obeys you. Put the wrong person in charge and the group fractures, the task fails — matching ability to role is the key to using people.", "ja": "力が足りないのに重い任を負い、位置も正しくなく、衆が従わない。人を誤って任せれば隊伍は割れ、事は成らない。能力を見て役を与えるのが用人の要だ。"},
  "7-3": {"zh": "你看清了进不去，就主动退一舍——这不丢人，反而守住了本分。退下来等时机，同时也是在整顿自己的队伍。", "en": "Seeing you can't advance, you pull back one station — no shame in that; you keep your footing. Retreating to wait for the moment is also a way to regroup your people.", "ja": "進めないと見て、一歩引いて宿を移す——恥ではなく、むしろ本分を守ること。引いて時を待つのは、同時に隊伍を整える道でもある。"},
  "7-4": {"zh": "你在上位，要用人就专心用一个人，把权力交给他，队伍才能统一。要是让好多人分着管、各管一摊，事情就坏了。", "en": "In charge, when you need someone for a task, put it in one person's hands — concentrated authority keeps the group united. Let many people split the power and the effort breaks down.", "ja": "上位にいて人を使うなら、一人に専任させ、権を委ねれば隊伍は統一される。多くの人に権を分たせれば、事は壊れる。"},
  "7-5": {"zh": "仗打完了，到了论功行赏的时候。功劳可以赏，但别把管人的权交出去——小人就算有功，赏他钱物可以，不能给他封地掌权。", "en": "The campaign is over; it's time to reward merit. Reward with honors but don't hand over governing power — even a base person who served can be rewarded with goods, but not given a fief to rule.", "ja": "戦いが終わり、功績を褒める時が来た。功は褒美として与えても、人を治める権は渡すな。小人に功があれば褒美を与えてよいが、国を任せてはならない。"},
  # 8 比
  "8-0": {"zh": "你跟人亲近，靠的是诚信。心里真有诚意，别人就不怀疑你——就算素不相识，也能亲得起来。", "en": "You draw close to others through sincerity. When faith is real inside, people don't doubt you — even strangers can become close.", "ja": "人と親しくする根本は誠実さ。心に誠がこもっていれば人は疑わず、初対面でも親しくなれる。"},
  "8-1": {"zh": "你的亲近是从心里发出来的，不是做样子——由自己推及别人，不用刻意去求，自然就合得来。", "en": "Your closeness comes from within, not as a show — extending from yourself to others, you don't have to seek it; it comes together on its own.", "ja": "親しさは内から湧き出たもので、作り物ではない。自分から人へ及ぼせば、求めずとも自然に合う。"},
  "8-2": {"zh": "你交的不是正经人——跟错了人，亲近反而变成拖累。挑对你要亲近的人，是立身的第一步。", "en": "You're involved with the wrong people — closeness to them becomes a burden. Choosing the right people to be close to is the first step in establishing yourself.", "ja": "付き合う相手を誤っている。間違った者と親しめば、かえって足を引っ張られる。誰と親しむかを選ぶのが、身を立てる第一歩だ。"},
  "8-3": {"zh": "你抛开自己那一伙人，转而去亲近上头有德有才的人——这叫以正从正。亲近贤者，你就找到了依靠。", "en": "You leave your private circle and draw close to the worthy person above — that's aligning right with right. Be close to the worthy and you find your support.", "ja": "私的な仲間を捨て、上にいる賢者に近づく——正をもって正に従うこと。賢者に親しめば、拠り所が得られる。"},
  "8-4": {"zh": "你在上位，光明正大地亲近众人、不偏私——来的人你接纳，走的人你不拦。不逼别人跟着你，所以没人提防你。", "en": "In the high place, you draw close to all openly and without favoritism — you welcome those who come and let those who leave go. You don't force others to follow you, so no one is on guard against you.", "ja": "高い位で、公明正大に衆と親しみ、私情を持たない。来る者は受け入れ、去る者は任せる。人に自分へ従うことを強いないので、誰も警戒しない。"},
  "8-5": {"zh": "你落在了最后，像大家都聚起来了你才姗姗来迟——这群人没有主心骨，亲近也就不成其为亲近。走到这一卦的尽头还没有归属，路就到头了。", "en": "You arrive last, like everyone has gathered and only then you show up — the group has no center, so closeness isn't real closeness. At the end of Bi with no one to belong to, the road ends.", "ja": "皆が集まってから遅れて来る——この集団に中心がなく、親しさも親しさでなくなる。比の極にいて拠り所がないなら、道は行き詰まっている。"},
}
